  return '<div class="split"><div class="panel co-list" role="group" aria-label="Companies">'+list+'</div>'+
    '<section class="panel"><div class="co-head">'+logoHTML(co.logo,co.name,52)+
      '<div><h2>'+esc(co.name)+'</h2><p>'+plural(co.units.length,"unit")+', '+active+' active</p></div>'+
      '<div class="co-btns">'+sw(co.active,"toggle-company",co.id,"Active: "+co.name)+'<button class="btn ghost" data-action="edit-company" data-id="'+co.id+'">'+I.edit+'Edit company</button>'+
      '<button class="btn ghost danger-text" data-action="del-company" data-id="'+co.id+'">'+I.del+'Delete</button></div></div>'+
    '<div class="co-units"><div class="toolbar"><h3>Units <span class="pill">'+co.units.length+'</span></h3>'+(co.units.length?searchBox("units","Search units"):'')+
      '<button class="btn" data-action="add-unit"'+(co.active?'':' disabled title="Activate the company to add units"')+'>'+I.plus+'Add unit</button></div>'+body+'</div></section></div>';
