/* ---------- Vendor KYC ---------- */
var REQ_LABEL={REQUIRED:"Required",CONDITIONAL:"Conditional",OPTIONAL:"Optional"};
function kycItem(kind,id){ if(!K) return null; return byId(kind==="FIELD"?K.fields:K.documents,id); }
function condText(c){ return c?"only when "+c.field_label+" is "+c.equals:""; }
function impactText(x){
  if(!x.catalog_active) return "Retired for every vendor type by the system.";
  if(x.locked) return x.locked_reason||"Always required.";
  var parts=[];
  if(!x.enabled){
    if(x.enable_impact.also_enables.length) parts.push("Turning it on also turns on <b>"+esc(names(x.enable_impact.also_enables))+"</b>.");
    return parts.join(" ")||"Not asked for this vendor type.";
  }
  if(x.disable_impact.also_disables.length) parts.push("Also turns off <b>"+esc(names(x.disable_impact.also_disables))+"</b>.");
  if(x.kind==="DOCUMENT"&&x.disable_impact.extraction_lost.length) parts.push("<b>"+esc(names(x.disable_impact.extraction_lost))+"</b> would no longer be filled from this document.");
  if(x.kind==="FIELD"){
    var ef=x.extracted_from.filter(function(d){ return d.effective; });
    parts.push("Vendors are no longer asked for it"+(ef.length?"; "+esc(names(ef))+" stops filling it.":"."));
  }
  return parts.join(" ")||"No other items depend on it.";
}
function kycRow(x){
  var flags=(x.label_override?'<span class="flag override" title="Wording set for this vendor type">Custom wording</span>':'')+
    (x.locked?'<span class="flag lock">'+I.lock+'Always on</span>':'')+(!x.catalog_active?'<span class="flag retired">Retired</span>':'');
  var sub=[condText(x.condition),x.note].filter(Boolean).join(" · ");
  var reason=!x.catalog_active?"Retired for every vendor type":x.locked?(x.locked_reason||"Always required"):null;
  return '<tr class="'+(x.effective?'':'off')+'"><td class="kyc-label"><b>'+esc(x.label)+'</b>'+flags+(sub?'<small>'+esc(sub)+'</small>':'')+'</td>'+
    '<td><span class="req '+x.requirement+'">'+REQ_LABEL[x.requirement]+'</span></td>'+
    '<td class="impact">'+impactText(x)+'</td>'+
    '<td class="status">'+sw(x.enabled,"kyc-toggle",x.kind+":"+x.id,(x.enabled?"Turn off ":"Turn on ")+x.label,reason)+'</td>'+
    '<td class="actions"><button class="icon-btn" data-action="kyc-detail" data-id="'+x.kind+":"+x.id+'" title="Dependencies" aria-label="Dependencies of '+esc(x.label)+'">'+I.flow+'</button>'+
    '<button class="icon-btn" data-action="kyc-label" data-id="'+x.kind+":"+x.id+'" title="Edit label" aria-label="Edit label of '+esc(x.label)+'"'+(x.catalog_active?'':' disabled')+'>'+I.edit+'</button></td></tr>';
}
function kycTable(rows,head){ return '<div class="table-wrap"><table class="kyc-table"><thead><tr><th>'+head+'</th><th>Requirement</th><th>What changes if it is turned off</th><th>On</th><th><span class="sr">Actions</span></th></tr></thead><tbody>'+rows+'</tbody></table></div>'; }
function kycSimple(){
  var m=match(ui.q.kyc), g=null, rows="";
  K.fields.filter(function(f){ return m(f.label,f.catalog_label,f.group_label); }).forEach(function(f){
    if(f.group_label!==g){ g=f.group_label; rows+='<tr><td colspan="5" class="kyc-group">'+esc(g)+'</td></tr>'; }
    rows+=kycRow(f);
  });
  var vendorDocs=K.documents.filter(function(d){ return d.origin!=="FINANCE"&&m(d.label,d.catalog_label); });
  var finDocs=K.documents.filter(function(d){ return d.origin==="FINANCE"&&m(d.label,d.catalog_label); });
  return '<section class="panel"><div class="panel-title">Documents the vendor uploads <span class="pill">'+vendorDocs.length+'</span></div>'+(vendorDocs.length?kycTable(vendorDocs.map(kycRow).join(""),"Document"):'<div class="empty">No documents match.</div>')+'</section>'+
    (finDocs.length?'<section class="panel"><div class="panel-title">Evidence Finance collects <span class="pill">'+finDocs.length+'</span></div>'+kycTable(finDocs.map(kycRow).join(""),"Document")+'</section>':'')+
    '<section class="panel"><div class="panel-title">Form fields <span class="pill">'+K.fields.length+'</span></div>'+(rows?kycTable(rows,"Field"):'<div class="empty">No fields match.</div>')+'</section>';
}
function chip(ref){ return '<span class="rchip'+(ref.effective?'':' off')+'" title="'+(ref.effective?'In use':'Currently off')+'">'+esc(ref.label)+'</span>'; }
function kycDependencies(){
  var controllers=K.fields.filter(function(f){ return f.controls.length; });
  var docs=K.documents.filter(function(d){ return d.extracts.length; });
  var locked=K.fields.concat(K.documents).filter(function(x){ return x.locked; });
  var retired=K.fields.concat(K.documents).filter(function(x){ return !x.catalog_active; });
  function sec(title,desc,items){ return '<section class="panel"><div class="panel-title">'+title+'</div><div class="dep-list">'+(items||'<p class="hint-inline">Nothing for this vendor type.</p>')+'</div></section>'+(desc?'':''); }
  return sec("Questions that decide other items","",controllers.map(function(f){
      return '<div class="dep"><div><h3>'+esc(f.label)+'</h3><p>Turning this off also turns off the items it decides.</p></div><div class="rlist">'+f.controls.map(chip).join("")+'</div></div>'; }).join(""))+
    sec("Documents that fill form fields","",docs.map(function(d){
      return '<div class="dep"><div><h3>'+esc(d.label)+'</h3><p>'+(d.extraction_active?'Values are suggested from the uploaded file; the vendor can always type them.':'Not used to fill fields right now (the document or its fields are off).')+'</p></div><div class="rlist">'+d.extracts.map(chip).join("")+'</div></div>'; }).join(""))+
    sec("Always asked","",locked.map(function(x){ return '<div class="dep"><div><h3>'+esc(x.label)+'</h3></div><p>'+esc(x.locked_reason||"")+'</p></div>'; }).join(""))+
    sec("Retired by the system","",retired.map(function(x){ return '<div class="dep"><div><h3>'+esc(x.label)+'</h3></div><p>No longer used for any vendor type. It cannot be turned on here.</p></div>'; }).join(""));
}
R.kyc=function(){
  if(status.kyc==="loading"||!K) return status.kyc==="error"?loadFailed("Vendor KYC configuration"):skeleton();
  var v=K.variant;
  var opts=K.variants.map(function(x){ return '<option value="'+esc(x.key)+'"'+(x.key===v.key?' selected':'')+'>'+esc(x.label)+'</option>'; }).join("");
  var when=v.updated_at?new Date(v.updated_at).toLocaleString():"";
  var bar='<div class="kyc-bar"><label class="sr" for="kyc-variant">Vendor type</label><select class="select" id="kyc-variant" data-kyc-variant>'+opts+'</select>'+
    '<div class="seg" role="group" aria-label="View"><button type="button" data-action="kyc-mode" data-id="simple" aria-pressed="'+(ui.kycMode==="simple")+'">Configuration</button>'+
    '<button type="button" data-action="kyc-mode" data-id="deps" aria-pressed="'+(ui.kycMode==="deps")+'">Dependencies</button></div>'+
    (ui.kycMode==="simple"?searchBox("kyc","Search fields or documents"):'')+
    '<span class="meta">Version '+esc(v.config_revision)+(when?' · changed '+esc(when):'')+(v.open_drafts?' · '+plural(v.open_drafts,"vendor")+' filling this form now':'')+'</span></div>';
  return bar+(ui.kycMode==="simple"?kycSimple():kycDependencies());
};

function kycDetail(x){
  function refs(list,empty){ return list.length?'<div class="rlist">'+list.map(chip).join("")+'</div>':'<p class="hint-inline">'+empty+'</p>'; }
  var body='<div class="dr-sec"><h3>For '+esc(K.variant.label)+'</h3><p><span class="req '+x.requirement+'">'+REQ_LABEL[x.requirement]+'</span> '+esc(condText(x.condition))+'</p>'+(x.note?'<p class="hint-inline">'+esc(x.note)+'</p>':'')+'</div>'+
    '<div class="dr-sec"><h3>Status</h3><p>'+(x.effective?"Asked for this vendor type.":x.enabled?"On, but not in use because something it depends on is off.":"Turned off for this vendor type.")+'</p></div>'+
    (x.controlled_by?'<div class="dr-sec"><h3>Depends on</h3>'+refs([x.controlled_by])+'</div>':'')+
    '<div class="dr-sec"><h3>Decides</h3>'+refs(x.controls,"No other items depend on this answer.")+'</div>'+
    (x.kind==="FIELD"?'<div class="dr-sec"><h3>Can be filled from</h3>'+refs(x.extracted_from,"Typed by the vendor only.")+'</div>'
                      :'<div class="dr-sec"><h3>Fills these fields</h3>'+refs(x.extracts,"This document is kept as evidence only.")+'</div>')+
    '<div class="dr-sec"><h3>If turned off</h3><p>'+impactText(x)+'</p></div>'+
    (x.label_override?'<div class="dr-sec"><h3>Wording</h3><p>Custom for this vendor type. Default: '+esc(x.catalog_label)+'</p></div>':'');
  openDrawer(x.label,x.kind==="FIELD"?"Form field":"Document",body);
}
function kycToggle(x){
  var change={kind:x.kind,id:x.id,enabled:!x.enabled};
  var base={variant_key:K.variant.key,expected_config_revision:K.variant.config_revision,changes:[change],apply_dependants:true};
  send("kycPreview",base).then(function(p){
    if(!p.changed){ toast("Nothing to change."); return; }
    var lines=[];
    function add(list,verb){ if(list&&list.length) lines.push("<li>"+verb+" <b>"+esc(names(list))+"</b></li>"); }
    add(p.applied.filter(function(c){return !c.enabled;}),"Turns off");
    add(p.applied.filter(function(c){return c.enabled;}),"Turns on");
    add(p.cascaded.filter(function(c){return !c.enabled;}),"Also turns off");
    add(p.cascaded.filter(function(c){return c.enabled;}),"Also turns on");
    if(p.impact.extraction.removed.length) lines.push("<li>Stops filling fields from <b>"+esc(names(p.impact.extraction.removed))+"</b> (vendors can still type them)</li>");
    if(p.impact.extraction.added.length) lines.push("<li>Starts filling fields from <b>"+esc(names(p.impact.extraction.added))+"</b></li>");
    var drafts=p.open_drafts_affected?'<div class="preview warn">'+plural(p.open_drafts_affected,"vendor")+' of this type '+(p.open_drafts_affected===1?'is':'are')+' filling the form right now. They see the change the next time they open or submit it. Submitted KYC is not affected.</div>':
      '<div class="preview info">Vendors of this type see the change the next time they open the form. Submitted KYC is not affected.</div>';
    openDialog({title:(change.enabled?"Turn on ":"Turn off ")+x.label+"?",sub:K.variant.label,saveLabel:"Apply change",done:"Vendor KYC configuration updated",
      body:'<div class="preview"><ul>'+lines.join("")+'</ul></div>'+drafts,
      save:function(){ return send("kycSave",base); }});
  },function(e){ failed(e); if(e.code==="CONFIG_REVISION_CONFLICT") send("kycLoad",{variant_key:K.variant.key}).catch(failed); });
}
function kycLabelForm(x){
  var hasOverride=!!x.label_override;
  openDialog({title:"Edit label",sub:x.kind==="FIELD"?"Form field":"Document",saveLabel:"Save label",done:"Label updated",
    body:field("label","Label shown to vendors and Finance",textInput("label",x.label,x.catalog_label),"Ids, rules and extraction do not change.")+
      '<div class="field" data-field="scope"><span class="lbl">Apply to</span><div class="radio-row">'+
      '<label><input type="radio" name="scope" value="VARIANT"'+(hasOverride?' checked':'')+'><span>Only <b>'+esc(K.variant.label)+'</b>. Leave empty to go back to the default wording.</span></label>'+
      '<label><input type="radio" name="scope" value="CATALOG"'+(hasOverride?'':' checked')+'><span>Every vendor type that uses the default wording (currently "'+esc(x.catalog_label)+'")</span></label>'+
