.drawer[hidden]{display:none}
.dr-body{padding:18px 22px;overflow-y:auto;display:flex;flex-direction:column;gap:16px}
.dr-sec h3{font-size:13px;font-weight:600;color:var(--mute);text-transform:uppercase;letter-spacing:.04em;margin-bottom:6px}
.dr-sec p{font-size:13.5px}
.radio-row{display:flex;flex-direction:column;gap:8px}
.radio-row label{display:flex;gap:8px;align-items:flex-start;font-size:13.5px;font-weight:400;color:var(--text)}
