"use strict";
/*
 * Finance > Admin Config custom widget.
 * Built on the team's Admin Config design (export snapshot 2026-09-25): same layout, tabs,
 * dialogs, confirm, toasts and styles. Data now comes from the backend workflows and every
 * change is a server-confirmed command; the widget owns no business rules:
 *   - model in : masters (WF_FIN_CFG_GetPrMasters), kyc (WF_FIN_CFG_GetKycConfig),
 *                result (command outcome), loadError
 *   - model out: command { id, action, payload } + triggerEvent("onCommand")
 *                -> page JS object AdminConfigApi.run()
 * Client-side checks below are instant feedback only; the workflows re-validate everything.
 */
function initAdminConfig(){
/* ================= Icons ================= */
var I = {
  edit:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 20h4L19 9l-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/></svg>',
  del:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/></svg>',
  x:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M18 6 6 18M6 6l12 12"/></svg>',
  plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M12 5v14M5 12h14"/></svg>',
  search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>',
  info:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 8h.01M11 12h1v5h1"/></svg>',
  mail:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16v12H4z"/><path d="m4 7 8 6 8-6"/></svg>',
  tick:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m5 12 5 5 9-10"/></svg>',
  lock:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="11" height="11"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>',
  flow:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="6" cy="6" r="2.5"/><circle cx="18" cy="18" r="2.5"/><path d="M8.5 6H14a4 4 0 0 1 4 4v5.5"/></svg>'
};

/* ================= Helpers ================= */
function $(s,r){ return (r||document).querySelector(s); }
function $$(s,r){ return Array.prototype.slice.call((r||document).querySelectorAll(s)); }
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function initials(n){ return String(n||"?").split(/\s+/).filter(Boolean).slice(0,2).map(function(w){return w[0];}).join("").toUpperCase(); }
var HUES = ["#2A74C6","#2C7A57","#8A4B9C","#A2582B","#2E6E7E","#7A5B1E","#5A6478","#9C3D54"];
function hue(s){ var h=0; s=String(s||""); for(var i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))>>>0; return HUES[h%HUES.length]; }
function avatar(name){ return '<span class="avatar" style="background:'+hue(name)+'">'+esc(initials(name))+'</span>'; }
function sw(on,action,id,label,disabled){ return '<button type="button" class="switch" role="switch" aria-checked="'+(!!on)+'" aria-label="'+esc(label)+'" data-action="'+action+'" data-id="'+esc(id)+'"'+(disabled?' disabled title="'+esc(disabled)+'"':'')+'></button>'; }
function rowActions(kind,id,name){
  return '<button class="icon-btn" data-action="edit-'+kind+'" data-id="'+id+'" aria-label="Edit '+esc(name)+'" title="Edit">'+I.edit+'</button>'+
         '<button class="icon-btn del" data-action="del-'+kind+'" data-id="'+id+'" aria-label="Delete '+esc(name)+'" title="Delete">'+I.del+'</button>';
}
function searchBox(key,ph){ return '<label class="search"><span class="sr">Search</span>'+I.search+'<input type="search" data-search="'+key+'" placeholder="'+esc(ph)+'" value="'+esc(ui.q[key]||"")+'"></label>'; }
function match(q){ q=(q||"").trim().toLowerCase(); return function(){ var s=Array.prototype.join.call(arguments," ").toLowerCase(); return !q||s.indexOf(q)>-1; }; }
function byId(list,id){ for(var i=0;i<list.length;i++) if(list[i].id===id) return list[i]; return null; }
function emailOk(e){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e); }
function plural(n,word){ return n+" "+word+(n===1?"":"s"); }
function names(list){ return list.map(function(x){ return x.label; }).join(", "); }

/* ================= Backend bridge ================= */
var S = {companies:[],departments:[],categories:[],authorities:[],stages:[]};
var K = null;
var status = {masters:"loading", kyc:"loading", error:null};
var seen = {masters:null, kyc:null, result:null, loadError:null};
var pending = null;
var ROLE_LABEL = {REQUESTER:"Requester", APPROVER:"Approver", DEPARTMENT_HEAD:"Department head"};

function fromMasters(m){
  function life(x){ return {id:x.id, revision:x.revision, active:x.status==="ACTIVE"}; }
  function logo(l){ return l && l.data_uri ? l.data_uri : null; }
  function rtext(r){ return r.type==="ROLE" ? (ROLE_LABEL[r.value]||r.value) : r.value; }
  return {
    companies:(m.companies||[]).map(function(c){ var o=life(c); o.name=c.name; o.logo=logo(c.logo);
      o.units=(c.units||[]).map(function(u){ var x=life(u); x.company_id=u.company_id; x.code=u.code; x.name=u.name; x.location=u.location||""; x.logo=logo(u.logo); return x; }); return o; }),
    departments:(m.departments||[]).map(function(d){ var o=life(d); o.name=d.name;
      o.subs=(d.sub_departments||[]).map(function(s){ var x=life(s); x.name=s.name; return x; }); return o; }),
    categories:(m.categories||[]).map(function(c){ var o=life(c); o.name=c.name; o.desc=c.description||""; return o; }),
    authorities:(m.authorities||[]).map(function(a){ var o=life(a); o.name=a.approver_name; o.email=a.approver_email; o.subs=(a.sub_department_ids||[]).slice(); o.min=a.amount_min; o.max=a.amount_max==null?null:a.amount_max; return o; }),
    stages:(m.stages||[]).map(function(s){ var r=s.recipients||{};
      return {id:s.id, revision:s.revision, name:s.name, when:s.trigger, enabled:!!s.enabled, proposal:s.definition_status!=="CONFIRMED",
              to:(r.to||[]).map(rtext), cc:(r.cc||[]).map(rtext), support:(r.support||[]).map(rtext)}; })
  };
}
function setBusy(b){ document.body.classList.toggle("is-busy",!!b); }
function send(action,payload){
  if(pending) return Promise.reject({code:"BUSY",message:"Another change is still being saved. Try again in a moment."});
  var id="cmd-"+Date.now()+"-"+Math.floor(Math.random()*1e6);
  return new Promise(function(resolve,reject){
    pending={id:id,resolve:resolve,reject:reject,timer:setTimeout(function(){
      if(pending&&pending.id===id){ pending=null; setBusy(false); reject({code:"TIMEOUT",message:"No answer from the server. Reload the page to check the current state before retrying."}); }
    },60000)};
    setBusy(true);
    appsmith.updateModel({command:{id:id,action:action,payload:payload||{}}});
    appsmith.triggerEvent("onCommand");
  });
}
function errText(e){ return (e&&e.message)||"Something went wrong."; }
function onModel(m){
  m=m||{};
  if(m.masters&&m.masters.loadedAt!==seen.masters){ seen.masters=m.masters.loadedAt; S=fromMasters(m.masters); status.masters="ready"; }
  if(m.kyc&&m.kyc.loadedAt!==seen.kyc){ seen.kyc=m.kyc.loadedAt; K=m.kyc; status.kyc="ready"; ui.kycVariant=K.variant.key; }
  if(m.loadError&&m.loadError.ts!==seen.loadError){ seen.loadError=m.loadError.ts; status.error=m.loadError;
    if(status.masters!=="ready") status.masters="error"; if(status.kyc!=="ready") status.kyc="error"; }
  var r=m.result;
  if(r&&r.id&&r.ts!==seen.result){ seen.result=r.ts;
    if(pending&&pending.id===r.id){ var p=pending; pending=null; clearTimeout(p.timer); setBusy(false);
      if(r.ok) p.resolve(r.data||{}); else p.reject(r.error||{code:"REQUEST_FAILED",message:"Request failed"}); } }
  render();
}

/* ================= Toast ================= */
function toast(msg,kind){
  var t=document.createElement("div"); t.className="toast"+(kind==="error"?" error":"");
  t.innerHTML='<span>'+esc(msg)+'</span>';
  $("#toasts").appendChild(t);
  setTimeout(function(){ t.remove(); }, kind==="error"?7000:3600);
}
function done(msg){ return function(res){ var w=res&&res.warnings&&res.warnings.length?" "+res.warnings.join(" "):""; toast(msg+w); return res; }; }
function failed(e){ toast(errText(e),"error"); }

/* ================= Confirm ================= */
var lastFocus=null, confirmCb=null;
function confirmDel(title,text,cb,okLabel){
  lastFocus=document.activeElement;
  $("#c-title").textContent=title; $("#c-text").textContent=text; confirmCb=cb;
  $("#c-ok").textContent=okLabel||"Delete";
  $("#scrim").classList.add("open"); $("#confirm").classList.add("open"); $("#c-cancel").focus();
}
function closeConfirm(){
  $("#confirm").classList.remove("open");
  if(!D) $("#scrim").classList.remove("open");
  confirmCb=null; if(lastFocus) lastFocus.focus();
}
$("#c-cancel").onclick=closeConfirm;
$("#c-ok").onclick=function(){ var cb=confirmCb; closeConfirm(); if(cb) cb(); };

/* ================= Dialog ================= */
var D=null;
var FIELD_FOR_CODE = {NAME_TAKEN:"name",CODE_TAKEN:"code",LOGO_INVALID:"logo",INVALID_AMOUNT_RANGE:"max",INVALID_RECIPIENT:"to",UNKNOWN_SUB_DEPARTMENT:"scope",PARENT_INACTIVE:null};
function openDialog(cfg){
  D=cfg; D.chips=cfg.chips||{}; lastFocus=document.activeElement;
  $("#d-title").textContent=cfg.title;
  $("#d-sub").textContent=cfg.sub||""; $("#d-sub").hidden=!cfg.sub;
  $("#d-save").textContent=cfg.saveLabel||"Save changes"; $("#d-save").disabled=false;
  $("#d-body").innerHTML='<div class="d-error" id="d-error" role="alert"></div>'+cfg.body; $("#d-body").scrollTop=0;
  $("#scrim").classList.add("open"); $("#dialog").classList.add("open");
  if(cfg.setup) cfg.setup($("#d-body"));
  setTimeout(function(){ var f=$("#d-body input:not([type=checkbox]):not([type=file]):not([type=radio]),#d-body textarea,#d-body select"); if(f) f.focus(); },60);
}
function closeDialog(){
  $("#dialog").classList.remove("open"); $("#scrim").classList.remove("open"); D=null;
  if(lastFocus&&document.body.contains(lastFocus)) lastFocus.focus();
}
$$("[data-close]").forEach(function(b){ b.onclick=function(){ if(!D||!D.saving) closeDialog(); }; });
$("#scrim").onclick=function(){ if($("#confirm").classList.contains("open")) closeConfirm(); else if(D&&!D.saving) closeDialog(); };
document.addEventListener("keydown",function(e){
  if(e.key!=="Escape") return;
  if($("#confirm").classList.contains("open")) closeConfirm(); else if(D&&!D.saving) closeDialog(); else if(!$("#drawer").hidden) closeDrawer();
});
function dialogError(err){
  var code=err&&err.code, name=FIELD_FOR_CODE[code];
  if(name&&$('[data-field="'+name+'"]',$("#d-body"))) invalid(name,errText(err));
  else $("#d-error").textContent=errText(err);
}
$("#d-form").addEventListener("submit",function(e){
  e.preventDefault(); if(!D||D.saving) return;
  $$(".field.invalid",$("#d-body")).forEach(function(f){ f.classList.remove("invalid"); });
  $("#d-error").textContent="";
  var r=D.save($("#d-body"));
  if(r===true){ var msg=D.done; closeDialog(); render(); toast(msg||"Changes saved"); return; }
  if(r&&typeof r.then==="function"){
    var cfg=D; cfg.saving=true; $("#d-save").disabled=true;
    r.then(function(res){ if(D!==cfg) return; closeDialog(); render(); done(cfg.done||"Changes saved")(res); },
           function(err){ if(D!==cfg) return; cfg.saving=false; $("#d-save").disabled=false; dialogError(err); });
  }
});
function invalid(name,msg){
  var f=$('[data-field="'+name+'"]',$("#d-body")); if(!f) return false;
  f.classList.add("invalid"); if(msg) $(".err",f).textContent=msg;
  var i=$("input:not([type=checkbox]):not([type=radio]),textarea,select",f); if(i) i.focus();
  return false;
}
function field(name,label,input,hint,extra){
  return '<div class="field" data-field="'+name+'"><div class="lbl-row"><label for="f-'+name+'">'+label+'</label>'+(extra||'')+'</div>'+input+
    (hint?'<div class="hint">'+hint+'</div>':'')+'<div class="err"></div></div>';
}
function textInput(name,v,ph,type){ return '<input class="input" id="f-'+name+'" name="'+name+'" type="'+(type||"text")+'" value="'+esc(v==null?"":v)+'" placeholder="'+esc(ph||"")+'" autocomplete="off">'; }
function val(root,name){ var el=$('[name="'+name+'"]',root); return el?el.value.trim():""; }

/* ================= Drawer (dependency detail) ================= */
function openDrawer(title,sub,body){
  $("#dr-title").textContent=title; $("#dr-sub").textContent=sub||""; $("#dr-body").innerHTML=body;
  $("#drawer").hidden=false; var b=$("[data-close-drawer]"); if(b) b.focus();
}
function closeDrawer(){ $("#drawer").hidden=true; }
$$("[data-close-drawer]").forEach(function(b){ b.onclick=closeDrawer; });

/* ================= UI state ================= */
var RECIPIENT_ROLES = ["Requester","Approver","Department head"];
var ui = {view:"companies",company:null,q:{},kycVariant:"LOCAL|RM",kycMode:"simple"};

var fmt = new Intl.NumberFormat("en-IN");
function inr(n){ return "₹"+fmt.format(n); }
function rangeText(a){ return a.max==null ? inr(a.min)+" and above" : inr(a.min)+" – "+inr(a.max); }
function dept(id){ return byId(S.departments,id); }
function subOwner(sid){
  for(var i=0;i<S.departments.length;i++){ var d=S.departments[i];
    for(var j=0;j<d.subs.length;j++) if(d.subs[j].id===sid) return {d:d,s:d.subs[j]}; }
  return null;
}
function scopeGroups(ids){
  return S.departments.map(function(d){
    var picked=d.subs.filter(function(s){ return ids.indexOf(s.id)>-1; });
    return picked.length?{d:d,picked:picked,all:picked.length===d.subs.length}:null;
  }).filter(Boolean);
}
function scopeText(ids){
  return scopeGroups(ids).map(function(g){
    return g.d.name+(g.all?" (all sub-departments)":" ("+g.picked.map(function(s){return s.name;}).join(", ")+")");
  }).join(", ");
}

/* ================= Logos ================= */
var LOGO_MAX=131072;
function logoHTML(logo,name,size){
  size=size||36;
  if(logo) return '<span class="logo" style="width:'+size+'px;height:'+size+'px;border:1px solid var(--rule-soft)"><img src="'+esc(logo)+'" alt=""></span>';
  return '<span class="logo" style="width:'+size+'px;height:'+size+'px;background:'+hue(name)+';font-size:'+Math.round(size*.36)+'px">'+esc(initials(name))+'</span>';
}
var D_logo=null;
function logoField(current,name,hint){
  D_logo=current||null;
  return '<div class="field" data-field="logo"><div class="lbl-row"><span class="lbl">Logo</span><span class="opt">Optional</span></div>'+
    '<div class="dropzone" id="dz"><span id="dz-prev">'+logoHTML(current,name||"?",56)+'</span><div><p>'+(hint||"PNG, JPG, SVG or WebP, up to 128 KB.")+' Drop a file here or choose one.</p>'+
    '<div class="links"><button type="button" class="linkish" id="dz-pick">Choose file</button><button type="button" class="linkish red" id="dz-rm"'+(current?'':' hidden')+'>Remove</button></div></div>'+
    '<input type="file" id="dz-file" accept="image/png,image/jpeg,image/svg+xml,image/webp" hidden></div><div class="err"></div></div>';
}
function wireLogo(root,nameSel){
  var dz=$("#dz",root), file=$("#dz-file",root), fld=$('[data-field="logo"]',root);
  function paint(){ $("#dz-prev",root).innerHTML=logoHTML(D_logo,$(nameSel,root).value||"?",56); $("#dz-rm",root).hidden=!D_logo; }
  function take(f){
    if(!f) return;
    if(["image/png","image/jpeg","image/svg+xml","image/webp"].indexOf(f.type)<0){ fld.classList.add("invalid"); $(".err",fld).textContent="Choose a PNG, JPG, SVG or WebP image."; return; }
    if(f.size>LOGO_MAX){ fld.classList.add("invalid"); $(".err",fld).textContent="This file is over 128 KB. Choose a smaller logo."; return; }
    fld.classList.remove("invalid");
    var r=new FileReader(); r.onload=function(){ D_logo=r.result; paint(); }; r.readAsDataURL(f);
  }
  $("#dz-pick",root).onclick=function(){ file.click(); };
  $("#dz-rm",root).onclick=function(){ D_logo=null; file.value=""; paint(); };
  file.onchange=function(){ take(file.files[0]); };
  dz.ondragover=function(e){ e.preventDefault(); dz.classList.add("drag"); };
  dz.ondragleave=function(){ dz.classList.remove("drag"); };
  dz.ondrop=function(e){ e.preventDefault(); dz.classList.remove("drag"); take(e.dataTransfer.files[0]); };
  $(nameSel,root).addEventListener("input",function(){ if(!D_logo) paint(); });
}
// undefined = unchanged, null = remove, object = new logo
function logoPayload(now,before){
  if(now===before) return undefined;
  if(!now) return null;
  var m=/^data:([^;,]+);base64,(.*)$/.exec(now); if(!m) return undefined;
  return {media_type:m[1],data_base64:m[2]};
}

/* ================= Recipient chips ================= */
function chipHTML(v,removable,kind){
  var cls = kind==="support" ? " support" : (RECIPIENT_ROLES.indexOf(v)>-1 ? " role" : "");
  return '<span class="rchip'+cls+'">'+esc(v)+(removable?'<button type="button" data-rm="'+esc(v)+'" aria-label="Remove '+esc(v)+'">'+I.x+'</button>':'')+'</span>';
}
function chipField(key,label,hint){
  return '<div class="field" data-field="'+key+'"><div class="lbl-row"><label for="ci-'+key+'">'+label+'</label></div><div class="chipin" data-chipin="'+key+'"></div>'+
    '<div class="suggest" data-suggest="'+key+'"></div>'+(hint?'<div class="hint">'+hint+'</div>':'')+'<div class="err"></div></div>';
}
function paintChips(root,key){
  var box=$('[data-chipin="'+key+'"]',root), list=D.chips[key], kind=key==="support"?"support":"";
  box.innerHTML=list.map(function(v){ return chipHTML(v,true,kind); }).join("")+
    '<input id="ci-'+key+'" placeholder="'+(list.length?'':(kind?'e.g. pr.support@jewelex.com':'Type an email and press Enter'))+'">';
  var sg=$('[data-suggest="'+key+'"]',root);
  sg.innerHTML=kind?'':RECIPIENT_ROLES.filter(function(r){ return list.indexOf(r)<0; }).map(function(r){ return '<button type="button" data-add="'+r+'">+ '+r+'</button>'; }).join("");
  sg.onclick=function(e){ var b=e.target.closest("[data-add]"); if(b){ list.push(b.getAttribute("data-add")); paintChips(root,key); } };
  var inp=$("input",box);
  inp.onkeydown=function(e){
    if(e.key==="Enter"||e.key===","||(e.key==="Tab"&&inp.value.trim())){ e.preventDefault(); addChip(root,key,inp.value); }
    else if(e.key==="Backspace"&&!inp.value&&list.length){ list.pop(); paintChips(root,key); $("#ci-"+key,root).focus(); }
  };
  inp.onblur=function(){ if(inp.value.trim()) addChip(root,key,inp.value,true); };
  box.onclick=function(e){
    var rm=e.target.closest("[data-rm]");
    if(rm){ list.splice(list.indexOf(rm.getAttribute("data-rm")),1); paintChips(root,key); $("#ci-"+key,root).focus(); }
    else if(e.target===box) inp.focus();
  };
}
function addChip(root,key,raw,silent){
  var v=raw.replace(/,/g,"").trim().toLowerCase(), fld=$('[data-field="'+key+'"]',root);
  if(!v) return;
  if(!emailOk(v)){ if(!silent){ fld.classList.add("invalid"); $(".err",fld).textContent=v+" is not a valid email address."; } return; }
  fld.classList.remove("invalid");
  if(D.chips[key].indexOf(v)<0) D.chips[key].push(v);
  paintChips(root,key); if(!silent) $("#ci-"+key,root).focus();
}

/* ================= Views ================= */
var VIEWS = {
  companies:{title:"Companies & units",desc:"Group companies raising purchase requests, and the units under each. Requesters pick these on the PR form.",action:["Add company","add-company"]},
  departments:{title:"Departments",desc:"The PR module uses its own department list. Requesters get their department from their profile and choose a sub-department.",action:["Add department","add-dept"]},
  categories:{title:"PR categories",desc:"What a purchase request is for. Inactive categories stay on old PRs but can't be chosen on new ones.",action:["Add category","add-cat"]},
  authorities:{title:"Approval authority",desc:"Who approves a PR, based on its department, sub-department and estimated amount.",action:["Add approver","add-auth"]},
  notifications:{title:"Email notifications",desc:"Who is emailed at each stage of a purchase request. Change recipients here without a code release. No email is sent from this screen.",action:null},
  kyc:{title:"Vendor KYC",desc:"Choose which existing KYC fields and documents each vendor type is asked for, and how they are labelled. Field rules, extraction and validation stay managed by the system.",action:null}
};
var R = {};
function skeleton(){ return '<div class="panel skeleton" aria-busy="true"><span></span><span></span><span></span></div>'; }
function loadFailed(what){ return '<div class="panel empty"><b>'+esc(what)+' could not be loaded</b>'+esc(status.error?status.error.message:"")+'<br><button class="btn" data-action="reload">Try again</button></div>'; }

function render(){
  var v=VIEWS[ui.view];
  $("#v-title").textContent=v.title; $("#v-desc").textContent=v.desc;
  var ready=status.masters==="ready";
  $("#v-actions").innerHTML=v.action&&ready?'<button class="btn" data-action="'+v.action[1]+'">'+I.plus+v.action[0]+'</button>':'';
  $$(".tab").forEach(function(t){ var on=t.getAttribute("data-view")===ui.view; t.setAttribute("aria-selected",on); t.tabIndex=on?0:-1; });
  var c=ready?{companies:S.companies.length,departments:S.departments.length,categories:S.categories.length,authorities:S.authorities.length,
         notifications:S.stages.filter(function(s){return s.enabled;}).length+"/"+S.stages.length}:{};
  c.kyc=K?K.variants.length:"";
  $$("[data-count]").forEach(function(el){ var x=c[el.getAttribute("data-count")]; el.textContent=x==null?"":x; });
  var banner=$("#banner");
  if(status.error&&(status.masters==="error"||status.kyc==="error")){ banner.hidden=false; banner.className="banner error"; banner.innerHTML=esc(status.error.message||"Loading failed.")+' <button class="btn ghost" data-action="reload">Try again</button>'; }
  else banner.hidden=true;
  var ae=document.activeElement, focused=ae&&ae.getAttribute&&ae.getAttribute("data-search"), caret=focused?ae.selectionStart:0;
  var html;
  if(ui.view==="kyc") html=R.kyc();
  else if(status.masters==="loading") html=skeleton();
  else if(status.masters==="error") html=loadFailed("Master data");
  else html=R[ui.view]();
  $("#view").innerHTML=html;
  if(focused){ var s=$('[data-search="'+focused+'"]'); if(s){ s.focus(); s.setSelectionRange(caret,caret); } }
}

/* ---------- Companies ---------- */
R.companies=function(){
