document.addEventListener("click",function(e){
  var b=e.target.closest("[data-action]"); if(!b||b.closest("#dialog")||b.disabled) return;
  var act=b.getAttribute("data-action"), id=b.getAttribute("data-id");
  var co=byId(S.companies,ui.company);
  function toggle(action,entity,op,label){ send(action,{op:op,id:entity.id,expected_revision:entity.revision,status:status2(entity.active)}).then(done(label+(entity.active?" deactivated":" activated")),failed); }
  switch(act){
    case "reload": status.error=null; if(status.masters==="error") status.masters="loading"; if(status.kyc==="error") status.kyc="loading"; render();
      return send("reload",{variant_key:ui.kycVariant}).catch(failed);
    case "add-company": return companyForm();
    case "edit-company": return companyForm(byId(S.companies,id));
    case "pick-company": ui.company=id; ui.q.units=""; return render();
    case "toggle-company": return toggle("company",byId(S.companies,id),"SET_COMPANY_STATUS",byId(S.companies,id).name);
    case "del-company":
      var c=byId(S.companies,id);
      if(c.units.length) return toast("Delete or move the "+plural(c.units.length,"unit")+" of "+c.name+" first.","error");
      return confirmDel("Delete "+c.name+"?","It disappears from the PR form. Existing PRs keep their company name.",function(){
        send("company",{op:"DELETE_COMPANY",id:c.id,expected_revision:c.revision}).then(function(r){ ui.company=null; return r; }).then(done(c.name+" deleted"),failed); });
    case "add-unit": return unitForm();
    case "edit-unit": return unitForm(byId(co.units,id));
    case "toggle-unit": return toggle("company",byId(co.units,id),"SET_UNIT_STATUS",byId(co.units,id).name);
    case "del-unit": var u=byId(co.units,id);
      return confirmDel("Delete "+u.name+"?","It disappears from the PR form. Existing PRs keep their unit.",function(){
        send("company",{op:"DELETE_UNIT",id:u.id,expected_revision:u.revision}).then(done(u.name+" deleted"),failed); });

    case "add-dept": return deptForm();
    case "edit-dept": return deptForm(dept(id));
    case "toggle-dept": return toggle("department",dept(id),"SET_DEPARTMENT_STATUS",dept(id).name);
    case "del-dept":
      var d=dept(id);
      if(d.subs.length) return toast("Delete the "+plural(d.subs.length,"sub-department")+" of "+d.name+" first.","error");
      return confirmDel("Delete "+d.name+"?","It disappears from the PR form and user profiles can no longer choose it.",function(){
        send("department",{op:"DELETE_DEPARTMENT",id:d.id,expected_revision:d.revision}).then(done(d.name+" deleted"),failed); });
    case "toggle-sub": var o=subOwner(id); return toggle("department",o.s,"SET_SUB_DEPARTMENT_STATUS",o.s.name);
    case "del-sub":
      var so=subOwner(id);
      return confirmDel("Delete "+so.s.name+"?","Approvers that still cover it must be edited first. Existing PRs keep it.",function(){
        send("department",{op:"DELETE_SUB_DEPARTMENT",id:so.s.id,expected_revision:so.s.revision}).then(done(so.s.name+" removed"),failed); });

    case "add-cat": return catForm();
    case "edit-cat": return catForm(byId(S.categories,id));
    case "toggle-cat": return toggle("category",byId(S.categories,id),"SET_CATEGORY_STATUS",byId(S.categories,id).name);
    case "del-cat": var k=byId(S.categories,id);
      return confirmDel("Delete "+k.name+"?","It can no longer be chosen on new PRs. Existing PRs keep it.",function(){
        send("category",{op:"DELETE_CATEGORY",id:k.id,expected_revision:k.revision}).then(done(k.name+" deleted"),failed); });

    case "add-auth": return authForm();
    case "edit-auth": return authForm(byId(S.authorities,id));
    case "toggle-auth": return toggle("authority",byId(S.authorities,id),"SET_AUTHORITY_STATUS",byId(S.authorities,id).name);
    case "del-auth": var a=byId(S.authorities,id);
      return confirmDel("Remove "+a.name+" as approver?","PRs will no longer be routed to this person.",function(){
        send("authority",{op:"DELETE_AUTHORITY",id:a.id,expected_revision:a.revision}).then(done(a.name+" removed as approver"),failed); },"Remove");

    case "edit-stage": return stageForm(byId(S.stages,id));
    case "toggle-stage": var st=byId(S.stages,id);
      return send("stage",{op:"SET_STAGE_ENABLED",id:st.id,expected_revision:st.revision,enabled:!st.enabled}).then(done(st.name+(st.enabled?" emails turned off":" emails turned on")),failed);

    case "kyc-mode": ui.kycMode=id; return render();
    case "kyc-toggle": return kycToggle(kycRef(id));
    case "kyc-detail": return kycDetail(kycRef(id));
    case "kyc-label": return kycLabelForm(kycRef(id));
  }
